import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Which customers a query returns. A customer matches only when it satisfies both parts.
 *
 * <p>The name is split on whitespace into terms, and every term must appear in the
 * customer's first name or last name. Case and accents are ignored on both sides, so
 * {@code makinen} matches {@code Mäkinen}. A blank name matches every customer.
 *
 * <p>The statuses, when any are given, must include the customer's status.
 *
 * @param name     the text typed into the name filter
 * @param statuses the statuses to accept; empty accepts every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /** Returns a predicate that accepts exactly the customers this filter matches. */
    public Predicate<Customer> asPredicate() {
        List<String> terms = terms(name);
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            String first = fold(customer.firstName());
            String last = fold(customer.lastName());
            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
        };
    }

    /** The folded search terms in the name; none when the name is blank. */
    private static List<String> terms(String name) {
        String folded = fold(name).strip();
        return folded.isEmpty() ? List.of() : List.of(WHITESPACE.split(folded));
    }

    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text.toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
    }
}
