+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1000, "Ada", "Aaltonen", "ada.aaltonen.1000@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            1001, "Joséphine", "Engberg", "josephine.engberg.1001@example.com", "Sweden", CustomerStatus.PENDING);
+    private static final Customer MAKINEN = new Customer(
+            1002, "Jarno", "Mäkinen", "jarno.makinen.1002@example.com", "Finland", CustomerStatus.CLOSED);
+
+    private static boolean matchesName(String name, Customer customer) {
+        return new CustomerFilter(name, Set.of()).asPredicate().test(customer);
+    }
+
+    @Test
+    void aBlankNameMatchesEveryCustomer() {
+        assertTrue(matchesName("", ADA));
+        assertTrue(matchesName("   ", ADA));
+    }
+
+    @Test
+    void everyTermMustAppearInTheFirstOrLastName() {
+        assertTrue(matchesName("ada aal", ADA));
+        assertTrue(matchesName("aal ada", ADA));
+        assertFalse(matchesName("ada virtanen", ADA));
+    }
+
+    @Test
+    void whitespaceAroundAndBetweenTermsIsNotSignificant() {
+        assertTrue(matchesName("  ada \t  aal  ", ADA));
+    }
+
+    @Test
+    void caseIsIgnored() {
+        assertTrue(matchesName("ADA", ADA));
+        assertTrue(matchesName("aaltonen", ADA));
+    }
+
+    @Test
+    void accentsAreIgnoredInBothDirections() {
+        assertTrue(matchesName("josephine", JOSEPHINE));
+        assertTrue(matchesName("makinen", MAKINEN));
+        assertTrue(matchesName("MÄKINEN", MAKINEN));
+    }
+
+    @Test
+    void statusesNarrowTheMatches() {
+        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)).asPredicate().test(ADA));
+        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.CLOSED)).asPredicate().test(ADA));
+    }
+
+    @Test
+    void theNameAndStatusMustBothMatch() {
+        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED));
+
+        assertFalse(filter.asPredicate().test(ADA));
+    }
+}
